const _wh = $('Webhook Updater').first().json || {};
const d = _wh.body || _wh;
const directive = String(d.directive || '');
const apply = d.apply_updates === true || /aplicar actualiz|apply updates|actualiza ahora/i.test(directive);
return [{json: {
  dry_run: !apply,
  directive,
  task_id: d.task_id || null,
  round_id: d.round_id || null,
  requested_by: d.requested_by || 'director'
}}];

const _wh = $('Webhook Updater').first().json || {};
const d = _wh.body || _wh;
const p = $('Preparar Updater').first().json || {};
const t = $('Tools Updater').first().json || {};
const h = $('Historial Updater').first().json || {};
const results = t.results || [];
const rolled = results.filter(r => r.rolled_back);
const failed = results.filter(r => !r.ok);
const updated = results.filter(r => r.ok && r.updated);
const findings = [];
if (rolled.length) findings.push({level:'CRIT', text:'Rollback ejecutado en: ' + rolled.map(r=>r.service).join(', ')});
if (failed.length) findings.push({level:'CRIT', text:'Fallos de actualización: ' + failed.map(r=>r.service).join(', ')});
if (updated.length) findings.push({level:'OK', text:'Actualizaciones aplicadas y sanas: ' + updated.map(r=>r.service).join(', ')});
if (!findings.length) findings.push({level:'OK', text:p.dry_run ? 'Ronda en seco: sin cambios; rollback garantizado si falla el healthcheck' : 'Sin cambios de digest disponibles'});
const severity = (rolled.length || failed.length) ? 'CRIT' : 'OK';
const evidence = JSON.stringify({dry_run:p.dry_run, results:results.slice(0,20), history:(h.updates||[]).slice(0,10)}).slice(0,4500);
const prompt = `Eres Agent-Updater, especialista en actualizaciones seguras de HomeLab Corp.
Tu jefe es HomeLab-Director. Informa en 3 a 5 líneas en español: servicios revisados,
digests antes/después, healthchecks verificados y si hubo rollback. Nunca propongas
borrar datos ni desactivar healthchecks. No inventes resultados.

MODO: ${p.dry_run ? 'SECO (sin cambios)' : 'APLICACIÓN REAL'}
EVIDENCIA:
${evidence}

HALLAZGOS:
${JSON.stringify(findings)}
`;
return [{json: {
  employee:'Agent-Updater', severity, quality_score:0.9, findings, evidence, prompt,
  directive:d.directive || p.directive || '', task_id:d.task_id || p.task_id || null,
  round_id:d.round_id || p.round_id || null, tool_data:t
}}];

const a = $('Analizar Updater').first().json || {};
const l = $('LLM Updater').first().json || {};
const choices = l.choices || [];
const text = ((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
return [{json: {
  employee: a.employee,
  severity: a.severity,
  quality_score: a.quality_score,
  summary: (text || a.summary || 'Sin hallazgos').slice(0, 2500),
  findings: a.findings || [],
  evidence: a.evidence || '',
  directive: a.directive || '',
  task_id: a.task_id || null,
  round_id: a.round_id || null
}}];

const r = $('Rendir cuentas Updater').first().json || {};
const d = $('Redactar informe Updater').first().json || {};
return [{json: {...d, report_id: r.report_id || null, ledger_ok: !!r.ok}}];
